import { Checkbox } from "@/registry/erbium/ui/checkbox";
import { useDragSelect } from "@/registry/erbium/hooks/use-drag-select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/registry/erbium/ui/table";
import {
  createColumnHelper,
  metaHelper,
  rowSelectionFeature,
  tableFeatures,
  useTable,
} from "@tanstack/react-table";

type User = {
  id: string;
  name: string;
  email: string;
  role: string;
};

const tableData: User[] = [
  { id: "1", name: "Sarah Chen", email: "sarah.chen@example.com", role: "Admin" },
  { id: "2", name: "Marcus Rodriguez", email: "marcus.rodriguez@example.com", role: "User" },
  { id: "3", name: "Priya Patel", email: "priya.patel@example.com", role: "User" },
  { id: "4", name: "David Kim", email: "david.kim@example.com", role: "Editor" },
];

const features = tableFeatures({
  rowSelectionFeature,
  columnMeta: metaHelper<{ selection?: boolean }>(),
});

const columnHelper = createColumnHelper<typeof features, User>();

const columns = columnHelper.columns([
  columnHelper.display({
    id: "select",
    header: ({ table }) => (
      <Checkbox
        aria-label="Select all rows"
        checked={table.getIsAllRowsSelected()}
        // v9's getIsSomeRowsSelected() is also true when every row is selected.
        indeterminate={table.getIsSomeRowsSelected() && !table.getIsAllRowsSelected()}
        onCheckedChange={(checked) => table.toggleAllRowsSelected(checked)}
      />
    ),
    cell: ({ row }) => (
      <Checkbox
        aria-label={`Select ${row.original.name}`}
        checked={row.getIsSelected()}
        disabled={!row.getCanSelect()}
        onCheckedChange={(checked) => row.toggleSelected(checked)}
      />
    ),
    meta: { selection: true },
  }),
  columnHelper.accessor("name", {
    header: "Name",
    cell: (info) => <span className="font-medium">{info.getValue()}</span>,
  }),
  columnHelper.accessor("email", { header: "Email" }),
  columnHelper.accessor("role", { header: "Role" }),
]);

export function CheckboxInTable() {
  const table = useTable({
    features,
    columns,
    data: tableData,
    getRowId: (row) => row.id,
    initialState: { rowSelection: { "1": true } },
  });
  const rows = table.getRowModel().rows;
  const dragSelect = useDragSelect({
    resolve(target) {
      const index = target.closest("tr")?.sectionRowIndex ?? -1;
      const row = rows[index];
      return row?.getCanSelect() ? { index, selected: row.getIsSelected() } : null;
    },
    selectRange(start, end, selected) {
      for (const row of rows.slice(start, end + 1)) {
        if (row.getCanSelect()) {
          row.toggleSelected(selected);
        }
      }
    },
  });

  return (
    <Table>
      <TableHeader>
        {table.getHeaderGroups().map((headerGroup) => (
          <TableRow key={headerGroup.id}>
            {headerGroup.headers.map((header) => (
              <TableHead
                className={header.column.columnDef.meta?.selection ? "w-8" : undefined}
                key={header.id}
              >
                {header.isPlaceholder ? null : <table.FlexRender header={header} />}
              </TableHead>
            ))}
          </TableRow>
        ))}
      </TableHeader>
      <TableBody {...dragSelect}>
        {rows.map((row) => (
          <TableRow data-state={row.getIsSelected() ? "selected" : undefined} key={row.id}>
            {row.getAllCells().map((cell) => (
              <TableCell
                className={cell.column.columnDef.meta?.selection ? "w-8" : undefined}
                key={cell.id}
              >
                <table.FlexRender cell={cell} />
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout"
    >
      {children}
    </div>
  );
}

import { cn } from "@/registry/erbium/lib/erbium-utils";
import { HugeiconsIcon } from "@hugeicons/react";
import MoreHorizontalIcon from "@hugeicons/core-free-icons/MoreHorizontalIcon";

import { Button } from "@/registry/erbium/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/registry/erbium/ui/dropdown-menu";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/registry/erbium/ui/table";
import { createColumnHelper, metaHelper, tableFeatures, useTable } from "@tanstack/react-table";

type Product = {
  id: string;
  name: string;
  price: number;
};

const products: Product[] = [
  { id: "mouse", name: "Wireless Mouse", price: 29.99 },
  { id: "keyboard", name: "Mechanical Keyboard", price: 129.99 },
  { id: "hub", name: "USB-C Hub", price: 49.99 },
];

const currency = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });

const features = tableFeatures({
  columnMeta: metaHelper<{ alignment?: "end"; narrow?: boolean }>(),
});

const columnHelper = createColumnHelper<typeof features, Product>();

const columns = columnHelper.columns([
  columnHelper.accessor("name", {
    header: "Product",
    cell: (info) => <span className="font-medium">{info.getValue()}</span>,
  }),
  columnHelper.accessor("price", {
    header: "Price",
    cell: (info) => currency.format(info.getValue()),
  }),
  // Display columns have no accessor; they render UI for each row.
  columnHelper.display({
    id: "actions",
    header: "Actions",
    cell: ({ row }) => (
      <DropdownMenu>
        <DropdownMenuTrigger render={<Button variant="ghost" size="icon" className="size-8" />}>
          <HugeiconsIcon icon={MoreHorizontalIcon} />
          <span className="sr-only">Open menu for {row.original.name}</span>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
          <DropdownMenuItem>Edit</DropdownMenuItem>
          <DropdownMenuItem>Duplicate</DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem variant="error">Delete</DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
    ),
    meta: { alignment: "end" },
  }),
]);

export function TableActions() {
  const table = useTable({ features, columns, data: products, getRowId: (row) => row.id });

  return (
    <Table>
      <TableHeader>
        {table.getHeaderGroups().map((headerGroup) => (
          <TableRow key={headerGroup.id}>
            {headerGroup.headers.map((header) => (
              <TableHead
                className={cn(
                  header.column.columnDef.meta?.alignment === "end" && "text-end",
                  header.column.columnDef.meta?.narrow && "w-25",
                )}
                key={header.id}
              >
                {header.isPlaceholder ? null : <table.FlexRender header={header} />}
              </TableHead>
            ))}
          </TableRow>
        ))}
      </TableHeader>
      <TableBody>
        {table.getRowModel().rows.map((row) => (
          <TableRow key={row.id}>
            {row.getAllCells().map((cell) => (
              <TableCell
                className={cn(
                  cell.column.columnDef.meta?.alignment === "end" && "text-end",
                  cell.column.columnDef.meta?.narrow && "w-25",
                )}
                key={cell.id}
              >
                <table.FlexRender cell={cell} />
              </TableCell>
            ))}
          </TableRow>
        ))}
      </TableBody>
    </Table>
  );
}

